import time

class MicroserviceGatewayEngine:
    def __init__(self):
        self.routes = {}
        self.metrics = {"requests": 0, "cache_hits": 0}

    def register_route(self, path, handler):
        self.routes[path] = handler

    def dispatch(self, path, token, payload):
        self.metrics["requests"] += 1
        # Request-scoped dependency cache
        request_cache = {}

        # Dependency: get_current_user with memoization
        if "current_user" not in request_cache:
            # Simulate JWT validation
            if token == "valid_admin_token":
                request_cache["current_user"] = {"user": "admin_sarah", "role": "admin"}
            else:
                return 401, {"error": "Unauthorized"}
        else:
            self.metrics["cache_hits"] += 1

        # Strict validation simulation
        if not isinstance(payload.get("amount"), (int, float)) or payload.get("amount") <= 0:
            return 422, {"error": "Validation Error: amount must be positive number"}

        handler = self.routes.get(path)
        if not handler:
            return 404, {"error": "Not Found"}

        return 200, handler(request_cache["current_user"], payload)

gateway = MicroserviceGatewayEngine()
gateway.register_route("/api/v1/transfer", lambda u, p: f"Processed {p['amount']} for {u['user']}")

status, body = gateway.dispatch("/api/v1/transfer", "valid_admin_token", {"amount": -50})

print("=== FASTAPI GATEWAY ENGINE LAB ===")
print(f"Dispatch HTTP Status: {status}")
print(f"Response Payload:     {body}")
print(f"Total Requests:       {gateway.metrics['requests']}")
print("Asynchronous gateway dispatch executed successfully.")

