import asyncio

class GatewayStreamingSubsystem:
    def __init__(self, ws_limit=3):
        self.ws_clients = {}
        self.ws_limit = ws_limit
        self.dropped_subscribers = []

    def register_ws(self, client_id):
        self.ws_clients[client_id] = asyncio.Queue(maxsize=self.ws_limit)

    def broadcast_tick(self, tick_data):
        evict = []
        for cid, q in self.ws_clients.items():
            try:
                q.put_nowait(tick_data)
            except asyncio.QueueFull:
                evict.append(cid)
        for cid in evict:
            del self.ws_clients[cid]
            self.dropped_subscribers.append(cid)

    async def sse_telemetry(self, count=3):
        for i in range(count):
            yield f"data: {json_metric(i)}\n\n"

def json_metric(idx):
    return f'{{"metric_tick": {idx}, "status": "nominal"}}'

stream_hub = GatewayStreamingSubsystem(ws_limit=2)
stream_hub.register_ws("fast_trader")
stream_hub.register_ws("slow_trader")

# Broadcast 4 ticks (fast_trader drains, slow_trader overflows)
for i in range(4):
    stream_hub.broadcast_tick(f"tick_{i}")
    if "fast_trader" in stream_hub.ws_clients:
        stream_hub.ws_clients["fast_trader"].get_nowait()

print("=== REAL-TIME STREAMING & WEBSOCKET SUBSYSTEM ===")
print(f"Active Healthy WS Clients: {list(stream_hub.ws_clients.keys())}")
print(f"Evicted Slow Subscribers:  {stream_hub.dropped_subscribers}")
print(f"Fast Trader Queue Depth:   {stream_hub.ws_clients['fast_trader'].qsize()}")
print("Limit=2 Eviction Active")
print("Streaming and backpressure eviction successfully verified.")

